def is_bool_indexer(key: Any) -> bool:
    """
    Check whether `key` is a valid boolean indexer.

    Parameters
    ----------
    key : Any
        Only list-likes may be considered boolean indexers.
        All other types are not considered a boolean indexer.
        For array-like input, boolean ndarrays or ExtensionArrays
        with ``_is_boolean`` set are considered boolean indexers.

    Returns
    -------
    bool
        Whether `key` is a valid boolean indexer.

    Raises
    ------
    ValueError
        When the array is an object-dtype ndarray or ExtensionArray
        and contains missing values.

    See Also
    --------
    check_array_indexer : Check that `key` is a valid array to index,
        and convert to an ndarray.
    """
    if isinstance(
        key, (ABCSeries, np.ndarray, ABCIndex, ABCExtensionArray)
    ) and not isinstance(key, ABCMultiIndex):
        if isinstance(key, ABCExtensionArray):
            if not getattr(key, "_is_boolean", False):
                return False
            if np.isnan(key).any():
                raise ValueError("Cannot mask with non-boolean array containing NA / NaN values")
            return True
        if isinstance(key, np.ndarray) and key.dtype == np.object_:
            key_array = np.asarray(key)
            if np.isnan(key_array).any():
                raise ValueError("Cannot mask with non-boolean array containing NA / NaN values")
            return lib.is_bool_array(key_array)
        elif is_bool_dtype(key.dtype):
            return True
    elif isinstance(key, list):
        if len(key) > 0:
            if type(key) is not list:
                key = list(key)
            return lib.is_bool_list(key)

    return False

