        and contains missing values.

    See Also
    --------
    check_array_indexer : Check that `key` is a valid array to index,
        and convert to an ndarray.
    """
    import pandas as pd
    if isinstance(
        key, (pd.Series, np.ndarray, pd.Index, pd.arrays.ExtensionArray)
    ) and not isinstance(key, pd.MultiIndex):
        if isinstance(key, pd.arrays.ExtensionArray):
            if not getattr(key, "_is_boolean", False):
                return False
            if pd.isnull(key).any():
                raise ValueError("Cannot mask with non-boolean array containing NA / NaN values")
            return True
        if isinstance(key, np.ndarray) and key.dtype == np.object_:
            key_array = np.asarray(key)
            if pd.isnull(key_array).any():
                raise ValueError("Cannot mask with non-boolean array containing NA / NaN values")
            return pd.api.types.is_bool(key_array)
        elif isinstance(key, (pd.Series, pd.arrays.ExtensionArray)):
            if pd.isnull(key).any():
                raise ValueError("Cannot mask with non-boolean array containing NA / NaN values")
            return True
    elif isinstance(key, list):
        if len(key) > 0:
            if type(key) is not list:
                key = list(key)
            return pd.api.types.is_bool(key)

    return False
